effect.shader:
float h(float x){return fract(sin(x*127.1)*43758.5453);}void main(){vec2 uv=acScreenNorm;float t=acTime*speed;vec3 light=vec3(0);float alpha=0.0,count=clamp(floor(bands+.5),1.0,10.0);for(int i=0;i<10;i++){if(float(i)>=count)break;float fi=float(i),seed=h(fi+2.0);float base=.25+height*(fi+.5)/count;float ribbon=base+sin(uv.x*frequency*6.2831853+t*(.7+seed))*0.07+sin(uv.x*frequency*2.7-t+seed*6.0)*0.035;float d=abs(uv.y-ribbon);float a=exp(-d/max(softness,.001))*(1.0-smoothstep(0.15,1.0,uv.y))/(1.0+fi*.3);vec3 c=mix(colorA.rgb,colorB.rgb,fract(fi*.37+uv.x*.2));light+=c*a;alpha+=a;}light*=intensity/count;alpha=clamp(alpha*intensity/count,0.0,1.0);vec4 src=texture2DCv(inputImg.texture,uv);vec3 outRgb=1.0-(1.0-src.rgb)*(1.0-clamp(light,0.0,1.0));gl_FragColor=vec4(mix(src.rgb,outRgb,mixAmount),src.a+alpha*mixAmount*(1.0-src.a));
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
